 "Vacuna": "Vaccin",
 "Años": "Années",
 "<b style=\"font-size:25px;color:#1f78b4\">Cifras redondeadas</b><br><span style=\"font-size:20px;color:#0f2b3d\">Datos aproximados para comparar.</span>": "<b style=\"font-size:25px;color:#1f78b4\">Chiffres arrondis</b><br><span style=\"font-size:20px;color:#0f2b3d\">Données approximatives pour comparer.</span>",
 "<b style=\"font-size:25px;color:#c27031\">Idea</b><br><span style=\"font-size:20px;color:#0f2b3d\">A veces la aplicación llega tarde.</span>": "<b style=\"font-size:25px;color:#c27031\">Idée</b><br><span style=\"font-size:20px;color:#0f2b3d\">Parfois l’application arrive tard.</span>",
