 "<b style=\"font-size:27px;color:#16928f\">Norte</b><br><span style=\"font-size:22px;color:#10302f\">Hacia donde apunta la brújula.</span>": "<b style=\"font-size:27px;color:#16928f\">Nord</b><br><span style=\"font-size:22px;color:#10302f\">Là où pointe la boussole.</span>",
